#!/usr/bin/env python3
"""M24.4d follow-up: does the ~2.5s bind-vs-include-reply gap measured by
`listener_race_probe.py` grow (or turn into an outright failure) under contention -- either (A)
two Renode processes booting at the same wall-clock time (pure CPU/scheduler contention, no
shared file), or (B) two Renode processes sharing `renode_bridge.py`'s own *hardcoded* generated
`.resc` path (hypothesis (e): a shared-mutable-file race, the actual defect this task's own
reading of `renode_bridge.py:212-213` found, independent of anything Renode does wrong).

Reuses `listener_race_probe.py`'s own functions directly -- not a reimplementation -- so this is
testing the exact same code path already characterised as a clean, isolated baseline.
"""
import json
import sys
import threading
import time

sys.path.insert(0, "/Users/probe/code/AltaVista/third_party/renode/M24_4d")
import listener_race_probe as p  # noqa: E402

SCRATCH = p.SCRATCH


def run_iteration_shared_resc(tag, shared_resc_path, results, start_barrier):
    """A near-duplicate of `listener_race_probe.run_one_iteration` except the `.resc` path is
    forced to a caller-supplied SHARED path (simulating renode_bridge.py's own hardcoded,
    non-scratch-dir path when two bridge instances are alive close together in time)."""
    monitor_port = p.free_tcp_port()
    uart_port = p.free_tcp_port()
    uart0_log = f"{SCRATCH}/conc_{tag}_uart0.log"
    renode_log_path = f"{SCRATCH}/conc_{tag}_renode_stdout.log"

    logf = open(renode_log_path, "wb")
    proc = p.subprocess.Popen(
        [p.RENODE_BIN, "--disable-gui", "--hide-log", "-P", str(monitor_port)],
        stdin=p.subprocess.DEVNULL, stdout=logf, stderr=p.subprocess.STDOUT,
    )
    record = {"tag": tag, "monitor_port": monitor_port, "uart_port": uart_port, "pid": proc.pid, "shared_resc_path": shared_resc_path}
    try:
        t0 = time.monotonic()
        sock = p.wait_for_port("127.0.0.1", monitor_port, t0 + 30.0)
        if sock is None:
            record["error"] = "monitor port never came up"
            results.append(record)
            return
        mon = p.MonitorClient(sock)
        mon.sock.settimeout(10.0)
        try:
            mon.sock.recv(65536)
        except OSError:
            pass

        # Every writer uses the SAME resc filename (hypothesis e) but with content tagged by
        # `tag`, so a reader that ends up seeing the OTHER writer's content is directly visible
        # in the machine name / uart0 log path it actually got wired to.
        resc_content = f'''# generated by concurrency_probe.py (writer {tag})
:name: av-m24-4d-conc-{tag}
using sysbus
using sysbus.cluster0
using sysbus.cluster1
mach create "av-m24-4d-conc-{tag}"
machine LoadPlatformDescription @{p.PLATFORM}
uart0 CreateFileBackend @{uart0_log} true
emulation CreateServerSocketTerminal $uartport "uart1_bridge_{tag}" false
connector Connect sysbus.uart1 uart1_bridge_{tag}
macro reset
"""
    cluster0 ForEach IsHalted true
    cluster1 ForEach IsHalted true
    rpu0 IsHalted false
    sysbus LoadELF @{p.ELF} cpu=rpu0
"""
runMacro $reset
'''
        mon.cmd(f"$uartport = {uart_port}")

        # Synchronize: every participant writes its own version of the shared file, then waits
        # at the barrier so all writes+includes are issued as close together as this harness can
        # arrange, maximising the chance of an actual overlap.
        start_barrier.wait()
        with open(shared_resc_path, "w") as f:
            f.write(resc_content)
        t_include_sent, include_chunks = mon.cmd(f"include @{shared_resc_path}", idle_gap=0.3, timeout=20.0)
        include_text = p.clean(b"".join(c for _, c in include_chunks))
        record["include_reply"] = include_text[:300]

        stop_event = threading.Event()
        samples = []
        poll_result = {}
        def poller():
            poll_result["first_listen_offset"] = p.poll_lsof_for_port(proc.pid, uart_port, stop_event, samples, budget_s=30.0)
        pt = threading.Thread(target=poller)
        pt.start()
        client = p.wait_for_port("127.0.0.1", uart_port, time.monotonic() + 20.0)
        record["tcp_connect_succeeded_within_20s"] = client is not None
        if client is not None:
            client.close()
        time.sleep(3.0)
        stop_event.set()
        pt.join(timeout=10.0)
        record["lsof_first_listen_offset_s"] = poll_result.get("first_listen_offset")

        # Which machine name does the monitor now report -- did this Renode process actually end
        # up loading the OTHER writer's content (proof of the resc-file race), or its own?
        name_reply = mon.cmd("using sysbus", idle_gap=0.3, timeout=5.0)
        record["post_include_prompt"] = p.clean(b"".join(c for _, c in name_reply[1]))[:200]

        final_lines, _ = p.lsof_listen_ports(proc.pid)
        record["final_lsof_listen_lines"] = final_lines
        # Read back what the uart0 CreateFileBackend actually targeted, by checking which log
        # file has content -- if THIS process's uart0_log stays empty while the OTHER tag's
        # uart0_log gets bytes meant for this one, that's direct proof of a cross-wired resc read.
    except Exception as e:
        record["exception"] = repr(e)
    finally:
        try:
            mon.send("quit")
        except Exception:
            pass
        try:
            proc.wait(timeout=10.0)
        except Exception:
            proc.kill()
            try:
                proc.wait(timeout=10.0)
            except Exception:
                pass
        results.append(record)


def main():
    mode = sys.argv[1] if len(sys.argv) > 1 else "shared"
    shared_path = f"{SCRATCH}/concurrency_shared.resc"
    results = []
    barrier = threading.Barrier(2)
    t_a = threading.Thread(target=run_iteration_shared_resc, args=("A", shared_path, results, barrier))
    t_b = threading.Thread(target=run_iteration_shared_resc, args=("B", shared_path, results, barrier))
    t_a.start()
    t_b.start()
    t_a.join(timeout=90)
    t_b.join(timeout=90)
    with open(f"{SCRATCH}/concurrency_probe_results.json", "w") as f:
        json.dump(results, f, indent=2, default=str)
    print(json.dumps(results, indent=2, default=str))


if __name__ == "__main__":
    main()
